import re,json
def keys(p):
    s=open(p,encoding='utf-8').read()
    return set(re.findall(r'^"([^"]+)"\s*=', s, re.M))
en=keys('Hanahuac/en.lproj/Localizable.strings')
es=keys('Hanahuac/es-ES.lproj/Localizable.strings')
print('en keys',len(en),'es-ES keys',len(es))
print('missing in es-ES:',sorted(en-es))
print('extra in es-ES:',sorted(es-en))

