for f,nk in [('countries.json',['name_es_es','capital_es_es']),('rivers.json',['name_es_es']),('mountains.json',['name_es_es']),('seas.json',['name_es_es'])]:
    data=json.load(open('Hanahuac/Resources/'+f,encoding='utf-8'))
    rows=data if isinstance(data,list) else data.get('items') or next(v for v in data.values() if isinstance(v,list))
    miss={k:[] for k in nk}
    eng_leftover=[]
    for r in rows:
        for k in nk:
            v=r.get(k)
            if not v: miss[k].append(r.get('id'))
